// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount, bool willAccept) public {
        amount = bound(amount, 0, 1 ether);

        Receiver helper = new Receiver(willAccept);

        vm.deal(address(c), amount);

        bool ok;
        try c.sendMoney(address(helper), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        if (willAccept) {
            assertTrue(address(helper).balance == amount);
        } else {
            assertTrue(address(helper).balance == 0);
        }
    }
}

contract Receiver {
    bool public accept;
    constructor(bool _accept) payable {
        accept = _accept;
    }
    fallback() external payable {
        if (!accept) revert("nope");
    }
    receive() external payable {
        if (!accept) revert("nope");
    }
}
